head.b:skin:
/* Blogger System Reset */
#navbar-iframe, .navbar, .header, #header, .feed-links, .status-msg-wrap { display: none !important; }
.blogger-hidden-section { display: none !important; visibility: hidden !important; height: 0 !important; width: 0 !important; overflow: hidden !important; }
html, body { margin: 0; padding: 0; width: 100%; min-height: 100%; background-color: #f8fafc; font-family: 'Hind Siliguri', -apple-system, BlinkMacSystemFont, sans-serif; }
#root { min-height: 100vh; display: flex; flex-direction: column; }

